# invoice-service

Creates and lists the invoices of the shop's customers. It has no dependencies: it runs on Node.js 22 or later alone.

`npm test` runs the tests in `test/`.

| Path | Holds |
|---|---|
| `lib/routes.js` | The HTTP routes, as one function from a request to a response |
| `lib/invoices.js` | Invoices and their totals |
| `lib/customers.js` | The customers, read from `lib/data/customers.json` |
| `lib/money.js` | Amounts, in cents |
| `lib/dates.js` | Calendar dates |
| `lib/config.js` | Settings read from environment variables |
| `lib/legacy/tax.js` | Tax rates, from the old billing system |
[
  { "id": "cus_003", "name": "Ana Lima", "email": "ana.lima@example.com", "region": "EU", "tier": "retail" },
  {
    "id": "cus_001",
    "name": "Bram de Vries",
    "email": "bram@example.org",
    "region": "EU",
    "tier": "wholesale"
  },
  {
    "id": "cus_004",
    "name": "Chloe Martin",
    "email": "chloe.martin@example.net",
    "region": "UK",
    "tier": "retail"
  },
  {
    "id": "cus_002",
    "name": "Dev Patel",
    "email": "dev.patel@example.com",
    "region": "US_CA",
    "tier": "retail"
  },
  {
    "id": "cus_005",
    "name": "Emil Novak",
    "email": "emil@examp// Tax rates by region, copied from the old billing system.
export const RATES = { EU: 2000, UK: 2000, US_CA: 725, US_NY: 400 };

/** Returns the tax on an amount in cents for a region, rounded to the cent. */
export function taxCents(totalCents, region) {
  return Math.round((totalCents * (RATES[region] ?? 0)) / 10_000);
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { addCents, formatCents } from '../lib/money.js';

test('adds amounts in cents', () => {
  assert.equal(addCents(150, 250, 5), 405);
});

test('formats cents with two decimals and the currency', () => {
  assert.equal(formatCents(1205, 'EUR'), '12.05 EUR');
  assert.equal(formatCents(-50, 'GBP'), '-0.50 GBP');
});

