import { formatCents } from './money.js';

/**
 * Logs one line saying an invoice was created, for which customer and for how much.
 * The customer is named by id only: log lines go to a third-party service and must not hold names or emails.
 */
export function logInvoiceCreated(invoice, log = console.log) {
  log(
    `Invoice ${invoice.id} created for customer ${invoice.customerId}, total ${formatCents(invoiceTotal(invoice), invoice.currency)}`,
  );
}

